import type { Metadata } from "next";
import type { ImageRef } from "@/lib/sanity/types";

export const SITE_NAME = "inkOrange Studios";
export const SITE_DESCRIPTION =
  "An independent studio making games that make you think. Sandboxes, puzzlers, simulations and more — for web, iOS and Android.";
export const SITE_LOCALE = "en_US";

/**
 * The site-wide share image generated by src/app/opengraph-image.tsx. A page that sets its own
 * `openGraph` replaces the inherited one, so pages without art name it explicitly.
 */
export const DEFAULT_SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "inkOrange Studios — Games that make you think.",
};

export type PageMetaInput = {
  title: string;
  /** Falls back to the site description so no page ships without one. */
  description?: string | null;
  /** Site-relative path ("/about"). metadataBase turns it into the full canonical URL. */
  path: string;
  /** Page-specific share image. Without one, DEFAULT_SHARE_IMAGE is used. */
  image?: ImageRef;
  /** Set for news posts: marks the page as an article with its publish date. */
  publishedTime?: string;
  noindex?: boolean;
};

/**
 * Full metadata for one page. Next merges metadata shallowly, so a page that sets `openGraph`
 * replaces the layout's whole block: every page goes through here to keep the site name, URL,
 * locale and Twitter card on all of them.
 */
export function pageMetadata({ title, description, path, image, publishedTime, noindex = false }: PageMetaInput): Metadata {
  const desc = description?.trim() || SITE_DESCRIPTION;
  const images = [image ? { url: image.src, width: image.width, height: image.height, alt: image.alt } : DEFAULT_SHARE_IMAGE];
  const shared = { siteName: SITE_NAME, locale: SITE_LOCALE, url: path, title, description: desc, images };

  return {
    title,
    description: desc,
    alternates: { canonical: path },
    openGraph: publishedTime ? { ...shared, type: "article", publishedTime } : { ...shared, type: "website" },
    twitter: { card: "summary_large_image", title, description: desc, images: images.map((i) => i.url) },
    ...(noindex ? { robots: { index: false, follow: true } } : {}),
  };
}

/** For a missing game or post: no canonical, kept out of the index. */
export const notFoundMetadata: Metadata = { title: `Page not found — ${SITE_NAME}`, robots: { index: false, follow: true } };
